tive" <?= selected(old('status',$company['status']??'active'),'active') ?>>Aktif</option><option value="inactive" <?= selected(old('status',$company['status']??''),'inactive') ?>>Nonaktif</option></select></div><div class="col-12"><label class="form-label">Alamat</label><textarea class="form-control" name="address" rows="3"><?= e(old('address',$company['address']??'')) ?></textarea></div></div><div class="form-actions"><a class="btn btn-light" href="<?= url('/companies') ?>">Batal</a><button class="btn btn-primary"><i class="bi bi-check2 me-1"></i>Simpan</button></div></form></div>
